import React,{useState,useEffect,useRef,useCallback} from 'react';
import {createRoot} from 'react-dom/client';
import {ArrowUpRight,ArrowRight,ArrowLeft,Heart,MessageCircle,Compass,ShieldCheck,SlidersHorizontal,MapPin,Plus,Check,X,Send,Video,Flag,UserRound,LogOut,LockKeyhole,ChevronDown,Search,Sparkles,Leaf,Headphones,BookOpen,Camera,Sun,Download,MoreHorizontal,EyeOff,CheckCheck,Menu,Settings,AlertTriangle,ShieldBan,Smile,Volume2,Info,LoaderCircle,ExternalLink} from 'lucide-react';
import {api,post} from './api';
import LiveVideoDialog from './LiveVideoDialog';
import RandomChat from './RandomChat';
import OwnerTraffic from './OwnerTraffic';
import CommunityActivity from './CommunityActivity';
import {startTraffic} from './traffic';
import ChatAuthDialog from './ChatAuthDialog';
import './styles.css';

const Brand=({small=false})=><span className={`brand ${small?'small':''}`}><span className="brand-icon"><Heart size={19} strokeWidth={2.2}/></span>HelloAgain<span className="brand-dot">.</span></span>;
const interestIcons={Coffee:'☕',Music:'♫',Travel:'↗',Books:'▤',Food:'◒',Outdoors:'❋',Art:'✳',Movies:'▷',Fitness:'↗',Gaming:'✧',Photography:'◉',Dogs:'♡'};
const initial=(s='?')=>s.trim().slice(0,1).toUpperCase();
const formatTime=s=>new Intl.DateTimeFormat(undefined,{hour:'numeric',minute:'2-digit'}).format(new Date(s));
function Avatar({person,size='normal',art=false}){return <div className={`avatar ${person.color||'peach'} ${size} ${art?'art':''}`} aria-label={`${person.name}'s illustrated avatar`}><span className="avatar-shape"/><span className="avatar-head"/><span className="avatar-body"/><span className="avatar-initial">{initial(person.name)}</span>{art&&<><span className="art-orbit"/><span className="art-spark">✳</span><span className="art-label">a little more {person.interests?.[0]?.toLowerCase()||'connection'}.</span></>}</div>;}
function Button({children,variant='',className='',busy=false,...props}){return <button className={`button ${variant} ${className}`} disabled={busy||props.disabled} {...props}>{busy?<LoaderCircle className="spin" size={17}/>:null}{children}</button>;}
function Empty({icon:Icon=Heart,title,children,action}){return <div className="empty"><span className="empty-icon"><Icon size={28}/></span><h3>{title}</h3><p>{children}</p>{action}</div>;}
function Modal({title,children,onClose,wide=false}){const ref=useRef(),closeRef=useRef(onClose);closeRef.current=onClose;useEffect(()=>{const previous=document.activeElement;const overflow=document.body.style.overflow;document.body.style.overflow='hidden';const root=ref.current;const focusable=()=>[...root.querySelectorAll('button,input,select,textarea,a[href]')].filter(x=>!x.disabled);focusable()[0]?.focus();function key(e){if([...document.querySelectorAll('[role=dialog]')].at(-1)!==root)return;if(e.key==='Escape')closeRef.current();if(e.key==='Tab'){const nodes=focusable(),first=nodes[0],last=nodes.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last?.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first?.focus();}}}document.addEventListener('keydown',key);return()=>{document.body.style.overflow=overflow;document.removeEventListener('keydown',key);previous?.focus();};},[]);return <div className="modal-backdrop" onMouseDown={e=>{if(e.target===e.currentTarget)onClose();}}><section className={`modal ${wide?'wide':''}`} role="dialog" aria-modal="true" aria-labelledby="modal-title" ref={ref}><header><h2 id="modal-title">{title}</h2><button className="icon-button" aria-label="Close dialog" onClick={onClose}><X size={21}/></button></header>{children}</section></div>;}
function Field({label,children,hint}){return <label className="field"><span>{label}</span>{children}{hint&&<small>{hint}</small>}</label>;}
function InterestPicker({value,onChange,options}){return <div className="interest-picker" aria-label="Choose interests">{options.map(i=><button type="button" key={i} aria-pressed={value.includes(i)} className={`chip ${value.includes(i)?'selected':''}`} onClick={()=>onChange(value.includes(i)?value.filter(v=>v!==i):value.length<6?[...value,i]:value)}><span>{interestIcons[i]}</span>{i}</button>)}</div>;}

function Landing({onAuth,onDemo,config,onPolicy}){return <div className="landing"><nav className="landing-nav"><Brand/><div className="landing-links"><a href="#how-it-works">How it works</a><button onClick={()=>onPolicy('guidelines')}>Our promise</button></div><Button variant="outline" onClick={()=>onAuth('login')}>Log in <ArrowUpRight size={15}/></Button></nav><main className="landing-main"><div className="hero-copy"><div className="eyebrow"><span/> A SPACE FOR SOMETHING REAL</div><h1>A little hello.<br/>A whole lot of<br/><em>possibility.</em><span className="hero-star">✳</span></h1><p>Less endless scrolling. More conversations that make you smile. Meet someone new, at your own pace.</p><Button onClick={()=>onAuth('signup')}>Find your kind of person <ArrowUpRight size={18}/></Button><div className="hero-footnote"><ShieldCheck size={16}/>18+ only · Mutual connections · Free text chat</div>{config?.demo&&<button className="text-link demo-link" onClick={onDemo}>Take a look around with sample profiles <ArrowRight size={15}/></button>}</div><div className="hero-art"><div className="hero-ring"/><div className="float-note top"><span>✦</span> Good conversations start here.</div><div className="hero-person first"><Avatar person={{name:'Maya',color:'peach',interests:['Music']}} art/><span className="hero-person-name">A shared playlist. A new beginning.</span></div><div className="hero-person second"><Avatar person={{name:'Alex',color:'sage',interests:['Coffee']}} art/></div><div className="float-note bottom"><span className="bubble-icon"><Heart size={20}/></span><div>A little spark?<small>Start with a hello.</small></div></div><span className="hero-sticker">be yourself.<br/>that’s enough.</span></div></main><section className="how-section" id="how-it-works"><div><span className="eyebrow">NO GRAND GESTURES REQUIRED</span><h2>Connection, without<br/>the complications.</h2></div><article><span>01</span><h3>Bring your real self</h3><p>A little about you. A few things you love. That’s a good place to start.</p></article><article><span>02</span><h3>Make it mutual</h3><p>Say hello to someone interesting. Conversation begins when you both accept.</p></article><article><span>03</span><h3>See where it goes</h3><p>Free text conversations, with blocking and reporting always within reach.</p></article></section><footer className="landing-footer"><Brand small/><span>A little kindness goes a long way.</span><div><button onClick={()=>onPolicy('privacy')}>Privacy</button><button onClick={()=>onPolicy('terms')}>Terms</button><button onClick={()=>onPolicy('guidelines')}>Guidelines</button></div></footer></div>;}

function AuthDialog(props){return <ChatAuthDialog {...props} Modal={Modal} Field={Field} Button={Button}/>;}

function ResetDialog({token,onClose,onDone}){const [password,setPassword]=useState(''),[repeat,setRepeat]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();if(password!==repeat){setError('Your passwords do not match.');return;}setBusy(true);try{await post('/auth/reset',{token,password});onDone();}catch(e){setError(e.message);}finally{setBusy(false);}}return <Modal title="A fresh start." onClose={onClose}><p className="muted modal-intro">Choose a new password. Reset links expire after 30 minutes and work only once. Existing sessions will be signed out.</p><form onSubmit={submit}><Field label="New password" hint="Use at least 12 characters."><input type="password" minLength={12} maxLength={256} required autoComplete="new-password" value={password} onChange={e=>setPassword(e.target.value)}/></Field><Field label="Repeat new password"><input type="password" minLength={12} maxLength={256} required autoComplete="new-password" value={repeat} onChange={e=>setRepeat(e.target.value)}/></Field>{error&&<div className="form-error" role="alert">{error}</div>}<Button className="full" type="submit" busy={busy}>Set new password <LockKeyhole size={16}/></Button></form></Modal>;}
function ProfileCard({person,onConnect,onOpen,onReport,busy}){const status=person.connectionStatus;return <article className="profile-card"><button className="profile-art-button" onClick={()=>onOpen(person)} aria-label={`View ${person.name}'s profile`}><Avatar person={person} art size="card"/>{person.isDemo&&<span className="sample-tag">Sample profile</span>}<span className="profile-art-arrow"><ArrowUpRight size={18}/></span></button><div className="profile-card-body"><div className="profile-heading"><button onClick={()=>onOpen(person)}><h3>{person.name}<span>, {person.age}</span></h3></button><button className="icon-button tiny" aria-label={`Report ${person.name}`} onClick={()=>onReport(person)}><MoreHorizontal size={19}/></button></div><div className="location"><MapPin size={12}/>{person.city}</div><p>{person.bio}</p><div className="tags">{person.interests.slice(0,3).map(i=><span key={i}><b>{interestIcons[i]}</b>{i}</span>)}</div><Button variant={status?'soft':'outline'} className="full connect-button" busy={busy} disabled={!!status&&status!=='accepted'&&!(status==='pending'&&person.incoming)} onClick={()=>onConnect(person)}>{status==='accepted'?<><MessageCircle size={15}/>Open conversation</>:status==='pending'&&person.incoming?<><Heart size={15}/>View invitation</>:status==='pending'?<><Check size={15}/>Hello sent</>:status==='declined'||status==='closed'?'Connection ended':<>Say hello <Plus size={15}/></>}</Button></div></article>;}

function Discover({people,onConnect,onOpen,onReport,onFilter,filters,onFilters,busy,user}){const [search,setSearch]=useState(''),[interest,setInterest]=useState('All interests');let shown=people.filter(p=>!['accepted','declined','closed'].includes(p.connectionStatus)&&p.age>=filters.min&&p.age<=filters.max&&(!filters.city||p.city.toLowerCase().includes(filters.city.toLowerCase()))&&(!filters.active||p.recentlyActive)&&(!search||`${p.name} ${p.city} ${p.bio}`.toLowerCase().includes(search.toLowerCase()))&&(interest==='All interests'||p.interests.includes(interest)));return <><div className="page-heading"><div><div className="eyebrow">A LITTLE CURIOSITY GOES A LONG WAY</div><h1>Someone new.<br className="mobile-break"/> Something <em>good.</em><span className="heading-star">✳</span></h1><p>You don’t need the perfect opening line. Just a little hello.</p></div><Button variant="outline" className="filter-button" onClick={onFilter}><SlidersHorizontal size={16}/>Your preferences</Button></div><div className="discovery-toolbar"><div className="discover-tabs"><button className={interest==='All interests'?'active':''} onClick={()=>setInterest('All interests')}>For you <span>{shown.length}</span></button><select aria-label="Filter by interest" value={interest} onChange={e=>setInterest(e.target.value)}><option>All interests</option>{['Coffee','Music','Travel','Books','Food','Outdoors','Art','Movies','Fitness','Gaming','Photography','Dogs'].map(i=><option key={i}>{i}</option>)}</select></div><label className="search-box"><Search size={16}/><input aria-label="Search people" placeholder="Find a little common ground" value={search} onChange={e=>setSearch(e.target.value)}/></label></div>{shown.length?<div className="profile-grid">{shown.map(p=><ProfileCard key={p.id} person={p} onConnect={onConnect} onOpen={onOpen} onReport={onReport} busy={busy===p.id}/>)}</div>:<Empty icon={Compass} title="A little room for possibility">{people.length?'Try another interest or broaden your preferences.':'New connections will appear here as people join. Invite an adult friend to try the local pilot.'}</Empty>}<div className="end-note"><Sparkles size={15}/><span>Good things take a little time. More hellos are on their way.</span></div></>;}

function Connections({connections,onRespond,onChat,busy}){const [tab,setTab]=useState('incoming');const incoming=connections.filter(c=>c.status==='pending'&&c.incoming),matches=connections.filter(c=>c.status==='accepted'),sent=connections.filter(c=>c.status==='pending'&&!c.incoming),shown=tab==='incoming'?incoming:tab==='matches'?matches:sent;return <><div className="page-heading"><div><div className="eyebrow">A HELLO GOES BOTH WAYS</div><h1>A little <em>mutual.</em><span className="heading-star">♡</span></h1><p>Good conversation begins when you both want to be there.</p></div></div><div className="section-tabs">{[['incoming','Received',incoming.length],['matches','Connections',matches.length],['sent','Sent',sent.length]].map(([key,label,count])=><button className={tab===key?'active':''} onClick={()=>setTab(key)} key={key}>{label}<span>{count}</span></button>)}</div>{shown.length?<div className="connection-grid">{shown.map(c=><article className="connection-card" key={c.id}><Avatar person={c.person} size="large"/><div className="connection-info"><h3>{c.person.name}, {c.person.age}</h3><div className="location"><MapPin size={12}/>{c.person.city}{c.person.isDemo?' · Sample profile':''}</div><p>{c.person.bio}</p><div className="tags">{c.person.interests.map(i=><span key={i}>{i}</span>)}</div></div><div className="connection-actions">{tab==='incoming'?<><Button busy={busy===c.id} onClick={()=>onRespond(c.id,true)}>Accept hello <Heart size={15}/></Button><Button variant="ghost" disabled={busy===c.id} onClick={()=>onRespond(c.id,false)}>No thanks</Button></>:tab==='matches'?<Button variant="outline" onClick={()=>onChat(c.id)}>Let’s talk <MessageCircle size={15}/></Button>:<span className="muted"><Check size={15}/> Waiting for a hello back</span>}</div></article>)}</div>:<Empty title={tab==='incoming'?'Your next hello is on its way.':tab==='matches'?'Make a little connection.':'Your first hello is waiting.'} icon={Heart}>{tab==='incoming'?'Invitations from people who want to meet you will appear here.':tab==='matches'?'Accept an invitation or say hello to someone in Discover.':'Find someone interesting in Discover and send a hello.'}</Empty>}</>;}

function Messages({connections,selected,onSelect,user,onReport,onVideo,onRefresh,notify}){const matches=connections.filter(c=>c.status==='accepted'),current=matches.find(c=>c.id===selected),[messages,setMessages]=useState([]),[draft,setDraft]=useState(''),[busy,setBusy]=useState(false),[loading,setLoading]=useState(false),[hasMore,setHasMore]=useState(false),[error,setError]=useState(''),[menu,setMenu]=useState(false);const bottom=useRef(),requestVersion=useRef(0),drafts=useRef({}),selectedRef=useRef(selected);selectedRef.current=selected;const scrollAfter=useRef(false);const fetchMessages=useCallback(async()=>{if(!selected)return;const id=selected;const data=await api(`/connections/${id}/messages`);if(selectedRef.current!==id)return;setMessages(old=>{if(old.length&&old.at(-1)?.id===data.messages.at(-1)?.id)return old;scrollAfter.current=true;return data.messages;});setHasMore(data.hasMore);setError('');if(document.visibilityState==='visible')await post(`/connections/${id}/read`);},[selected]);useEffect(()=>{setDraft(drafts.current[selected]||'');setMenu(false);setMessages([]);setError('');setLoading(!!selected);fetchMessages().catch(e=>setError(e.message)).finally(()=>setLoading(false));if(!selected)return;const interval=setInterval(()=>{if(!document.hidden)fetchMessages().catch(e=>setError(e.message));},2500);return()=>clearInterval(interval);},[selected,fetchMessages]);useEffect(()=>{if(scrollAfter.current){bottom.current?.scrollIntoView({behavior:'smooth',block:'nearest'});scrollAfter.current=false;}},[messages]);async function send(e){e.preventDefault();if(!draft.trim()||!current||busy)return;const text=draft,id=selected;setBusy(true);try{const data=await post(`/connections/${id}/messages`,{body:text});if(selectedRef.current===id){setMessages(old=>old.some(m=>m.id===data.message.id)?old:[...old,data.message]);setDraft('');scrollAfter.current=true;}drafts.current[id]='';onRefresh();}catch(e){notify(e.message,'error');}finally{setBusy(false);}}async function older(){try{const id=selected;const data=await api(`/connections/${id}/messages?before=${messages[0].id}`);if(selectedRef.current!==id)return;setMessages(old=>[...data.messages,...old]);setHasMore(data.hasMore);}catch(e){notify(e.message,'error');}}async function close(){try{await post(`/connections/${selected}/close`);onSelect(null);onRefresh();notify('Connection ended.');}catch(e){notify(e.message,'error');}}return <div className={`messages-layout ${current?'has-chat':''}`}><aside className="conversation-list"><div className="conversation-list-title"><h2>Your conversations<span>.</span></h2><p>A little hello can go a long way.</p></div>{matches.length?matches.map(c=><button className={`conversation-item ${c.id===selected?'active':''}`} onClick={()=>onSelect(c.id)} key={c.id}><Avatar person={c.person}/><div><strong>{c.person.name}{c.unread>0&&<span className="unread-dot"/>}</strong><p>{c.lastMessage?.body||'You connected. Say your first hello!'}</p></div>{c.lastMessage&&<time>{formatTime(c.lastMessage.created_at)}</time>}</button>):<Empty icon={MessageCircle} title="No conversations yet">Connect with someone first. Both people need to accept.</Empty>}</aside><section className="chat-panel">{current?<><header className="chat-header"><button className="icon-button chat-back" aria-label="Back to conversations" onClick={()=>onSelect(null)}><ArrowLeft size={19}/></button><Avatar person={current.person}/><div className="chat-person"><h3>{current.person.name}</h3><span>{current.person.isDemo?'Fictional sample profile':current.person.recentlyActive?'Recently active':'Your mutual connection'}</span></div><button className="icon-button" aria-label="Video call setup" onClick={()=>onVideo({...current.person,connectionId:current.id})}><Video size={21}/></button><div className="menu-wrap"><button className="icon-button" aria-expanded={menu} aria-label="Conversation options" onClick={()=>setMenu(!menu)}><MoreHorizontal size={22}/></button>{menu&&<div className="dropdown-menu"><button onClick={()=>{setMenu(false);onReport(current.person);}}><Flag size={16}/>Report or block</button><button onClick={close}><X size={16}/>End connection</button></div>}</div></header><div className="chat-trust"><LockKeyhole size={13}/>Only you and your connection can access this chat. Reports may share recent messages with moderators.</div><div className="chat-messages" aria-live="polite" aria-label="Conversation messages">{hasMore&&<button className="text-link older" onClick={older}>Load earlier messages</button>}{loading?<div className="loading-inline"><LoaderCircle className="spin" size={20}/>Opening your conversation…</div>:!messages.length&&!error?<div className="first-message"><Heart size={24}/><h3>You both said hello.</h3><p>Start with something small. Ask about something they love.</p></div>:null}{messages.map(m=><div key={m.id} className={`message ${m.senderId===user.id?'mine':''}`}><p>{m.body}</p><span>{formatTime(m.createdAt)}{m.senderId===user.id&&<Check size={11}/>}</span></div>)}{error&&<div className="form-error" role="alert">{error}</div>}<div ref={bottom}/></div><form className="message-composer" onSubmit={send}><textarea aria-label="Your message" placeholder={`Say something to ${current.person.name}…`} value={draft} maxLength={4000} rows={1} onChange={e=>{setDraft(e.target.value);drafts.current[selected]=e.target.value;}} onKeyDown={e=>{if(e.key==='Enter'&&!e.shiftKey&&!e.nativeEvent.isComposing){e.preventDefault();send(e);}}}/><span className="message-count">{draft.length}/4000</span><button className="send-button" type="submit" aria-label="Send message" disabled={!draft.trim()||busy||!!error}>{busy?<LoaderCircle className="spin" size={18}/>:<Send size={19}/>}</button></form><p className="composer-note">No daily text quota. A short sending limit helps prevent spam.</p></>:<Empty icon={MessageCircle} title="A conversation worth having.">Pick a connection on the left and make their day a little more interesting.</Empty>}</section></div>;}

function ReportDialog({person,onClose,onDone}){const [reason,setReason]=useState('harassment'),[detail,setDetail]=useState(''),[block,setBlock]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState('');async function submit(e){e.preventDefault();setBusy(true);try{await post('/reports',{target:person.id,reason,detail,block});onDone(block?'Report sent. This person is also blocked.':'Report sent for moderator review.');onClose();}catch(e){setError(e.message);}finally{setBusy(false);}}async function blockOnly(){setBusy(true);try{await post('/blocks',{target:person.id});onDone('This person is blocked.');onClose();}catch(e){setError(e.message);}finally{setBusy(false);}}return <Modal title={`Report ${person.name}`} onClose={onClose}><p className="muted modal-intro">You deserve a respectful space. Reports are private and reviewed by a moderator.</p><form onSubmit={submit}><Field label="What happened?"><select value={reason} onChange={e=>setReason(e.target.value)}><option value="harassment">Harassment or threatening behaviour</option><option value="black_screen">Black, covered, or switched-off camera</option><option value="nudity">Nudity or exposed private parts</option><option value="shirtless">Shirtless appearance</option><option value="sexual_activity">Sexual activity</option><option value="underage">Possibly under 18</option><option value="spam">Spam or scam</option><option value="impersonation">Fake identity or impersonation</option><option value="other">Something else</option></select></Field><Field label="Anything else we should know?" hint="Do not include identity documents or sensitive personal information."><textarea rows={4} maxLength={2000} value={detail} onChange={e=>setDetail(e.target.value)}/></Field><label className="check-row"><input type="checkbox" checked={block} onChange={e=>setBlock(e.target.checked)}/><span>Also block {person.name} and end our connection immediately.</span></label><div className="notice"><Info size={17}/><p>Submitting shares up to 10 recent messages with moderators. A report triggers review; confirmed violations result in a ban.</p></div>{error&&<div className="form-error" role="alert">{error}</div>}<Button type="submit" className="full" busy={busy}>Send report <Flag size={16}/></Button><Button type="button" variant="ghost" className="full" disabled={busy} onClick={blockOnly}>Just block this person</Button></form></Modal>;}

function VideoDialog({person,onClose,config}){return <LiveVideoDialog person={person} onClose={onClose} Modal={Modal} config={config}/>;}

function Safety({onPolicy,onVideo}){return <><div className="page-heading"><div><div className="eyebrow">KINDNESS IS THE STARTING POINT</div><h1>Feel good about<br/>saying <em>hello.</em><span className="heading-star">✳</span></h1><p>Your boundaries matter. Here’s how we look after them.</p></div></div><div className="safety-banner"><ShieldCheck size={38}/><div><h2>A little respect. No exceptions.</h2><p>Adults only. Mutual consent. Camera visible. Shirts stay on for everyone.</p></div></div><div className="safety-grid">{[[Heart,'Make it mutual','Pressing Start joins the live queue. Chat begins when another eligible adult has also pressed Start. Next or Stop ends contact.'],[ShieldBan,'Block without explaining','Blocking ends your connection and prevents further messages. You will not be matched with that account again.'],[Flag,'Speak up. We’ll review.','Report harassment, scams, underage concerns, or prohibited exposure. Confirmed violations lead to a ban; suspected cases need review.'],[Video,'Strict video boundaries','Black, covered, or switched-off cameras and unclothed appearances are prohibited. Keep the lens uncovered, turn on a light, and stay visible and fully clothed. Live calls require both people to press Start and pass on-server camera screening.'],[LockKeyhole,'Keep personal things personal','Avoid sharing your address, financial details, intimate images, or identity documents. Never send money to someone you just met.'],[UserRound,'Take your time','Declared age and gender do not verify identity. Meet in a public place, tell someone your plans, and leave if you feel uncomfortable.']].map(([Icon,title,copy])=><article className="safety-card" key={title}><Icon size={24}/><h3>{title}</h3><p>{copy}</p></article>)}</div><div className="safety-links"><Button variant="outline" onClick={()=>onPolicy('guidelines')}>Read community guidelines <ArrowUpRight size={16}/></Button><Button variant="ghost" onClick={()=>onVideo(null)}>Check camera setup <Camera size={16}/></Button></div></>;}

function PreferencesDialog({filters,onClose,onSave,user,onUser,notify}){const [form,setForm]=useState({...filters,min:user.ageMin,max:user.ageMax}),[busy,setBusy]=useState(false),[error,setError]=useState('');async function save(e){e.preventDefault();if(form.min>form.max){setError('Minimum age must be no higher than maximum age.');return;}setBusy(true);try{const data=await api('/profile',{method:'PUT',body:{name:user.name,city:user.city,bio:user.bio,interests:user.interests,color:user.color,visible:user.visible,ageMin:form.min,ageMax:form.max}});onUser(data.user);onSave(form);onClose();notify('Your preferences are saved.');}catch(e){setError(e.message);}finally{setBusy(false);}}return <Modal title="Your kind of connection." onClose={onClose}><p className="muted modal-intro">Age preferences are saved to your account. City and activity filters apply in this browser session.</p><form onSubmit={save}><div className="form-row"><Field label="Minimum age"><input type="number" min="18" max="99" value={form.min} onChange={e=>setForm({...form,min:Number(e.target.value)})} required/></Field><Field label="Maximum age"><input type="number" min="18" max="99" value={form.max} onChange={e=>setForm({...form,max:Number(e.target.value)})} required/></Field></div><Field label="City"><input placeholder="Any city" maxLength={60} value={form.city} onChange={e=>setForm({...form,city:e.target.value})}/></Field><label className="check-row"><input type="checkbox" checked={form.active} onChange={e=>setForm({...form,active:e.target.checked})}/><span>Show people active in the last five minutes</span></label>{error&&<div className="form-error" role="alert">{error}</div>}<Button className="full" type="submit" busy={busy}>Save preferences <Check size={16}/></Button></form></Modal>;}

function ProfileSettings({user,onUser,config,notify,onLogout}){const [form,setForm]=useState({name:user.name,city:user.city,bio:user.bio,interests:user.interests,color:user.color,visible:user.visible,ageMin:user.ageMin,ageMax:user.ageMax}),[busy,setBusy]=useState(false),[blocks,setBlocks]=useState([]),[deleteOpen,setDeleteOpen]=useState(false);useEffect(()=>{api('/blocks').then(d=>setBlocks(d.blocks)).catch(e=>notify(e.message,'error'));},[]);const set=(k,v)=>setForm({...form,[k]:v});async function save(e){e.preventDefault();setBusy(true);try{const d=await api('/profile',{method:'PUT',body:form});onUser(d.user);notify('Account changes saved.');}catch(e){notify(e.message,'error');}finally{setBusy(false);}}async function exportData(){try{const data=await api('/account/export');const url=URL.createObjectURL(new Blob([JSON.stringify(data,null,2)],{type:'application/json'}));const a=document.createElement('a');a.href=url;a.download='helloagain-my-data.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);notify('Your data export is ready.');}catch(e){notify(e.message,'error');}}async function unblock(id){try{await api(`/blocks/${id}`,{method:'DELETE',body:{}});setBlocks(b=>b.filter(x=>x.id!==id));notify('Person unblocked. The previous connection stays closed.');}catch(e){notify(e.message,'error');}}return <><div className="page-heading"><div><div className="eyebrow">A LITTLE MORE YOU</div><h1>Your little <em>corner.</em></h1><p>Manage your account details and privacy choices.</p></div></div><CommunityActivity userId={user.id}/><div className="settings-layout"><form className="settings-card" onSubmit={save}><div className="settings-profile"><Avatar person={{...user,color:form.color}} size="large"/><div><h3>{user.name}, {user.age}</h3><p>{user.email}</p><span className="pill">{user.gender==='man'?'Man':'Woman'} · Declared identity</span></div></div><Field label="Display name"><input value={form.name} onChange={e=>set('name',e.target.value)} minLength={2} maxLength={40} required/></Field><p className="muted">Your email and date of birth stay private. Choose Random to meet any eligible adult, or choose Women / Men to meet the opposite gender. Both people’s choices are respected.</p><Button type="submit" busy={busy} >Save account <Check size={16}/></Button></form><aside className="settings-side"><section className="settings-card"><h3>Your data, your decision.</h3><p className="muted">Download your account information and messages you sent. Text messages are kept for up to 90 days.</p><Button variant="outline" className="full" onClick={exportData}><Download size={16}/>Download my data</Button></section><section className="settings-card"><h3>Blocked people</h3>{blocks.length?blocks.map(b=><div className="blocked-row" key={b.id}><span>{b.name}</span><button className="text-link" onClick={()=>unblock(b.id)}>Unblock</button></div>):<p className="muted">Nobody on this list. Use Report / block during a live chat.</p>}</section><section className="settings-card danger-zone"><h3>Leave on your own terms.</h3><p className="muted">Delete your account, profile, connections, and messages. This cannot be undone.</p><Button variant="danger-outline" onClick={()=>setDeleteOpen(true)}>Delete my account</Button></section></aside></div>{deleteOpen&&<DeleteDialog onClose={()=>setDeleteOpen(false)} onDone={onLogout} user={user}/>}</>;}
function DeleteDialog({onClose,onDone,user}){const [password,setPassword]=useState(''),[confirmation,setConfirmation]=useState(''),[error,setError]=useState(''),[busy,setBusy]=useState(false);async function submit(e){e.preventDefault();setBusy(true);try{await api('/account',{method:'DELETE',body:{password,confirmation}});onDone();}catch(e){setError(e.message);}finally{setBusy(false);}}return <Modal title="Delete your account?" onClose={onClose}><p className="muted modal-intro">Your profile, sessions, connections, and chats will be deleted. Report evidence involving your account will be cleared. This cannot be undone.</p>{user.isDemo&&<div className="notice"><Info size={16}/><p>This is a shared local sample account. Use a newly created account to test deletion instead.</p></div>}<form onSubmit={submit}><Field label="Your password"><input type="password" value={password} onChange={e=>setPassword(e.target.value)} autoComplete="current-password" required/></Field><Field label="Type DELETE to confirm"><input value={confirmation} onChange={e=>setConfirmation(e.target.value)} pattern="DELETE" required/></Field>{error&&<div className="form-error" role="alert">{error}</div>}<Button variant="danger" type="submit" className="full" busy={busy} disabled={confirmation!=='DELETE'}>Permanently delete account</Button></form></Modal>;}

const policies={
 guidelines:{title:'A little respect. Every time.',intro:'Community guidelines · Adults 18+ only',sections:[['Keep your camera on and your picture clear','Black screens, covered lenses, switched-off cameras, and blank replacement pictures are not allowed during a call. Allow camera access, turn on a light, and keep yourself clearly visible. Prohibited feeds must be stopped immediately; users can end, block, and report contact at once. Confirmed intentional violations result in an immediate ban. Technical failures require correction and are not automatic proof of misconduct.'],['Keep your shirt on','Everyone must remain clothed. Shirtless appearance, nudity, exposed private parts, sexual activity, and requests for prohibited exposure are not allowed. Confirmed violations result in an immediate account ban.'],['Make consent the starting point','Random conversation starts when both adults press Start. Respect someone using Next or Stop. Do not threaten, harass, pressure, stalk, impersonate, spam, or solicit money.'],['Protect children','Nobody under 18 may use this service. Child sexual abuse and exploitation are prohibited. Report suspected minors or exploitation immediately using the report button; the operator must maintain a child-safety response process before launch.'],['What happens after a report','Blocking immediately ends contact. Reports are reviewed by the operator. Suspected violations may result in suspension. Confirmed violations result in a ban. False or malicious reports are also subject to review.'],['Appeals and support','Use the operator’s published support contact to appeal a moderation decision. This local build has no public support address; a real contact and staffed process must be provided before launch.'],['Video availability','Your local preview stays on your device. The pre-call check sends a picture to this server for screening. During a call, every transmitted picture is screened on this server before delivery. Automated flags stop the call and suspend the account pending review; detection can miss violations or make mistakes. No detection system can guarantee prevention of exposure.']]},
 privacy:{title:'Your privacy, in plain words.',intro:'Local build privacy notice · Version 21 October 2026 · Requires operator details before public launch',sections:[['What is stored','Email address, a salted password hash, declared date of birth and gender, name, city, interests, profile text, preferences, session records, connections, text messages, blocks, reports, and moderation actions. We do not collect exact location or identity documents. Illustrated avatars are used instead of photo uploads.'],['Who can see what','The random-chat home page has no profile directory. Your chat partner receives your display name and declared gender; your older optional profile fields are not included in the random-call response. Signed-in members can see aggregate counts of accounts active in the last two minutes, split by declared gender. These counts do not include names, emails or individual activity histories. Date of birth, email, and password hashes are not public. Chat is accessible to its two participants through the server. It is not end-to-end encrypted. Administrators can see reported message excerpts and necessary account information.'],['Reports and moderation','A report can share up to 10 recent conversation messages with moderators. Calls are not recorded. The pre-call camera check and live video frames are processed in server memory for screening; audio is relayed through that server. Your local preview is not recorded. Flag labels and scores may be retained for moderation review; camera images and audio are not retained.'],['Retention and deletion','Messages are removed after 90 days. Report message excerpts are cleared after 30 days; reports and moderation audit entries are removed after 90 days. Expired sessions and rate-limit records are cleaned up at startup and hourly while the server runs. Account deletion removes profile, sessions, connections, and chats and clears report evidence involving the account. Backup retention must be configured separately before launch.'],['Account email','When an email provider is configured, password-recovery emails share your email address and reset-link contents with that provider for delivery. Passwords and camera media are not sent to the email provider. Provider retention and contact details must be published for the hosted service.'],['Cookies and advertising','A first-party HTTP-only session cookie keeps you signed in for up to seven days. This build has no advertising scripts or third-party cookies. First-party traffic measurement counts visible homepage loads and a broad source category, such as Instagram. Only the owner can view these totals. No IP addresses, account details, chat content or camera media are stored in traffic data. Daily aggregates are retained for 90 days, a running total is retained while the service operates, and random per-page retry IDs expire after 24 hours. Do Not Track and Global Privacy Control requests are excluded. An owner-browser preference in local storage prevents counting the site owner’s own browser. Private messages are not used for advertising. Any later advertising requires updated disclosures and appropriate consent.'],['Your choices','Edit your display name, block people, download your own data, or permanently delete your account in Your account. For this local pilot, age is self-declared; it is not verified.'],['Before public launch','The operator must publish its identity, privacy/support contact, launch jurisdictions, hosting locations, processors, lawful processing basis, rights procedure, breach process, age assurance approach, and backup policy. This notice describes the local software and is not a completed jurisdiction-specific legal policy.']]},
 terms:{title:'A good place to start.',intro:'Local pilot terms · Version 21 October 2026 · Operator details pending',sections:[['Who can join','You must be 18 or older and provide accurate information. Choose Random to meet adults of any declared gender, or Women / Men for opposite-gender matching. Both participants’ choices must allow the match. Profiles and identity are not independently verified in this local build.'],['Free text, fair use','There is no daily text-message quota. Sending and invitation limits prevent spam and protect service availability. Infrastructure capacity is finite; uptime and future free operation are not guaranteed.'],['Community rules','You must accept the community guidelines. No shirtless appearance, nudity, exposed private parts, sexual activity, harassment, exploitation, fraud, or impersonation. Confirmed violations result in a ban.'],['Your choices and responsibility','Both adults must press Start before random chatting. You can report, block, close a connection, or delete your account. Use caution when sharing personal information or meeting offline.'],['Moderation and appeals','Reports may share recent conversation excerpts. The operator can suspend suspected violations, ban confirmed violations, and review appeals. A report alone does not establish a violation. A public support contact is required before launch.'],['Local preview status','Sample profiles are fictional and labelled. The local build has no configured production email delivery, verified age assurance, or public support team. Local video screening is automated and still requires a staffed review process before public launch. Live video requires both adults to press Start and active server screening. Operator-specific terms and applicable legal review are required before public use.']]}
};
function PolicyDialog({kind,onClose}){const p=policies[kind];return <Modal title={p.title} onClose={onClose} wide><p className="policy-intro">{p.intro}</p><div className="policy-content">{p.sections.map(([title,body])=><section key={title}><h3>{title}</h3><p>{body}</p></section>)}</div></Modal>;}

function Admin({notify}){const [data,setData]=useState(null),[tab,setTab]=useState('reports'),[busy,setBusy]=useState(''),[decision,setDecision]=useState(null),[note,setNote]=useState('');async function load(){try{setData(await api('/admin/overview'));}catch(e){notify(e.message,'error');}}useEffect(()=>{load();},[]);async function decide(e){e.preventDefault();setBusy(decision.id);try{if(decision.kind==='report')await post(`/admin/reports/${decision.id}/resolve`,{action:decision.action,note});else await post(`/admin/users/${decision.id}/status`,{status:decision.action,note});setDecision(null);setNote('');notify('Moderation decision recorded.');await load();}catch(e){notify(e.message,'error');}finally{setBusy('');}}if(!data)return <div className="loading-inline"><LoaderCircle size={20} className="spin"/>Loading moderation…</div>;const open=data.reports.filter(r=>r.status==='open');return <><div className="page-heading"><div><div className="eyebrow">LOOKING AFTER THE COMMUNITY</div><h1>A safer <em>hello.</em></h1><p>Review evidence. Record a reason. Give people a fair decision.</p></div><Button variant="outline" onClick={load}>Refresh queue</Button></div><div className="admin-stats"><div><strong>{open.length}</strong><span>Open reports</span></div><div><strong>{data.users.filter(u=>u.status==='active').length}</strong><span>Active accounts</span></div><div><strong>{data.users.filter(u=>u.status==='banned').length}</strong><span>Banned accounts</span></div></div><div className="section-tabs">{['reports','accounts','audit'].map(t=><button key={t} onClick={()=>setTab(t)} className={tab===t?'active':''}>{t==='reports'?'Reports':t==='accounts'?'Accounts':'Decision history'}</button>)}</div>{tab==='reports'?(data.reports.length?data.reports.map(r=><article className="report-card" key={r.id}><div className="report-title"><h3>{r.reason.replaceAll('_',' ')} <span className={`status-pill ${r.status}`}>{r.status}</span></h3><time>{new Date(r.created_at).toLocaleString()}</time></div><p><strong>{r.reporter_name||'Deleted account'}</strong> reported <strong>{r.target_name||'Deleted account'}</strong></p><p className="report-detail">{r.detail||'No additional detail provided.'}</p>{r.context.length>0&&<details><summary>Reported message context ({r.context.length})</summary><div className="evidence">{r.context.map((m,i)=><p key={i}><strong>{m.sender_id===r.target?r.target_name:r.reporter_name}:</strong> {m.body}</p>)}</div></details>}{r.status==='open'&&<div className="report-actions">{[['ban','Confirm violation & ban'],['suspend','Suspend for review'],['dismiss','Dismiss report']].map(([action,label])=><Button key={action} variant={action==='ban'?'danger-outline':'outline'} disabled={action!=='dismiss'&&!r.target} onClick={()=>{setNote('');setDecision({kind:'report',id:r.id,action,name:r.target_name});}}>{label}</Button>)}</div>}</article>):<Empty icon={ShieldCheck} title="A quiet queue is a good thing.">Reports will appear here for review. There are no unresolved reports.</Empty>):tab==='accounts'?<div className="account-table-wrap"><table className="account-table"><thead><tr><th>Member</th><th>Status</th><th>Role</th><th>Action</th></tr></thead><tbody>{data.users.map(u=><tr key={u.id}><td><strong>{u.name}</strong><small>{u.email}</small></td><td><span className={`status-pill ${u.status}`}>{u.status}</span></td><td>{u.role}</td><td><Button variant="ghost" onClick={()=>{setNote('');setDecision({kind:'user',id:u.id,action:u.status==='active'?'suspended':'active',name:u.name});}}>{u.status==='active'?'Suspend':'Restore'}</Button></td></tr>)}</tbody></table></div>:<div className="audit-list">{data.audit.length?data.audit.map(a=><article key={a.id}><ShieldCheck size={18}/><div><strong>{a.action} · {a.target_name||'Deleted account'}</strong><p>{a.note}</p><small>{a.actor_name||'Deleted admin'} · {new Date(a.created_at).toLocaleString()}</small></div></article>):<Empty title="No decisions yet.">Decisions and their reasons appear here.</Empty>}</div>}{decision&&<Modal title={`${decision.action==='ban'?'Ban':decision.action==='suspend'||decision.action==='suspended'?'Suspend':decision.action==='dismiss'?'Dismiss report for':'Restore'} ${decision.name||'account'}?`} onClose={()=>setDecision(null)}><p className="muted modal-intro">{decision.action==='ban'?'Confirm that you have reviewed the evidence and verified a community rule violation. This immediately revokes their sessions and prevents messaging.':'Record the reason for this decision. It will be kept in the moderation history.'}</p><form onSubmit={decide}><Field label="Decision reason"><textarea required minLength={5} maxLength={500} rows={4} value={note} onChange={e=>setNote(e.target.value)}/></Field><Button className="full" variant={decision.action==='ban'?'danger':''} busy={!!busy} type="submit">Confirm decision</Button></form></Modal>}</>;}

function App(){const [config,setConfig]=useState(null),[user,setUser]=useState(null),[boot,setBoot]=useState(true),[bootError,setBootError]=useState(''),[view,setView]=useState(()=>window.location.pathname==='/owner/traffic'?'traffic':'video'),[people,setPeople]=useState([]),[connections,setConnections]=useState([]),[auth,setAuth]=useState(null),[policy,setPolicy]=useState(null),[report,setReport]=useState(null),[video,setVideo]=useState(undefined),[detail,setDetail]=useState(null),[prefs,setPrefs]=useState(false),[selected,setSelected]=useState(null),[busy,setBusy]=useState(''),[toast,setToast]=useState(null),[filters,setFilters]=useState({min:18,max:99,city:'',active:false}),[installPrompt,setInstallPrompt]=useState(null),[mobileMenu,setMobileMenu]=useState(false),[incomingCall,setIncomingCall]=useState(null),[resetToken,setResetToken]=useState(()=>new URLSearchParams(window.location.search).get('reset'));const sessionId=useRef(null);sessionId.current=user?.id;const refreshInFlight=useRef(false);const notify=useCallback((message,type='success')=>setToast({message,type,time:Date.now()}),[]);useEffect(()=>{if(!toast)return;const timer=setTimeout(()=>setToast(null),5500);return()=>clearTimeout(timer);},[toast]);
 const refresh=useCallback(async()=>{if(!sessionId.current||refreshInFlight.current)return;refreshInFlight.current=true;const id=sessionId.current;try{const [d,c]=await Promise.all([Promise.resolve({people:[]}),api('/connections')]);if(sessionId.current===id){setPeople(d.people);setConnections(c.connections);}}catch(e){if(e.status===401||e.status===403){setUser(null);notify(e.message,'error');}else notify(e.message,'error');}finally{refreshInFlight.current=false;}},[notify]);
 async function initialize(){setBoot(true);setBootError('');try{const [c,m]=await Promise.all([api('/config'),api('/me')]);setConfig(c);setUser(m.user);if(m.user)setFilters(f=>({...f,min:m.user.ageMin,max:m.user.ageMax}));}catch(e){setBootError(e.message);}finally{setBoot(false);}}
 useEffect(()=>{initialize();if(new URLSearchParams(window.location.search).has('reset'))window.history.replaceState(null,'',window.location.pathname);const onInstall=e=>{e.preventDefault();setInstallPrompt(e);};window.addEventListener('beforeinstallprompt',onInstall);return()=>window.removeEventListener('beforeinstallprompt',onInstall);},[]);
 useEffect(()=>{if(!user){setConnections([]);setPeople([]);setSelected(null);return;}refresh();const timer=setInterval(()=>{if(!document.hidden)refresh();},5000);return()=>clearInterval(timer);},[user?.id,refresh]);
 useEffect(()=>{if(!user){setIncomingCall(null);return;}let cancelled=false;async function check(){try{const data=await api('/video/status');if(cancelled)return;setConfig(old=>old&&old.videoEnabled===data.ready?old:{...old,videoEnabled:data.ready});setIncomingCall(data.calls.find(c=>c.incoming&&c.status==='ringing')??null);}catch{}}check();const timer=setInterval(()=>{if(!document.hidden)check();},2000);return()=>{cancelled=true;clearInterval(timer);};},[user?.id]);
 useEffect(()=>{if(!boot&&!bootError)return startTraffic(user);},[boot,bootError,user?.id,user?.canViewTraffic]);
 useEffect(()=>{const change=()=>setView(window.location.pathname==='/owner/traffic'?'traffic':'video');window.addEventListener('popstate',change);return()=>window.removeEventListener('popstate',change);},[]);
 const updateUser=u=>{setUser(u);setFilters(f=>({...f,min:u.ageMin,max:u.ageMax}));};
 async function demo(){setBusy('demo');try{const d=await post('/auth/demo');updateUser(d.user);setView('video');notify('Local preview opened. Sample profiles are fictional.');}catch(e){notify(e.message,'error');}finally{setBusy('');}}
 async function logout(){try{await post('/auth/logout');setUser(null);setView('video');}catch(e){notify(e.message,'error');}}
 function navigate(v){setView(v);setMobileMenu(false);const path=v==='traffic'?'/owner/traffic':'/';if(window.location.pathname!==path)window.history.pushState(null,'',path);}
 function openChat(id){setSelected(id);navigate('messages');}
 async function connect(p){if(p.connectionStatus==='accepted'){openChat(p.connectionId);return;}if(p.incoming){navigate('connections');return;}setBusy(p.id);try{await post('/connections',{target:p.id});notify(`A little hello is on its way to ${p.name}.`);await refresh();}catch(e){notify(e.message,'error');}finally{setBusy('');}}
 async function respond(id,accept){setBusy(id);try{await post(`/connections/${id}/respond`,{accept});await refresh();notify(accept?'You both said hello. Your conversation is open.':'Invitation declined.');if(accept)openChat(id);}catch(e){notify(e.message,'error');}finally{setBusy('');}}
 const invitations=connections.filter(c=>c.status==='pending'&&c.incoming).length,unread=connections.reduce((s,c)=>s+c.unread,0);
 const nav=[['video','Live chat',Video],['profile','Your account',UserRound],['safety','Safety & rules',ShieldCheck]];
 return <>{boot?<div className="boot"><Brand/><LoaderCircle className="spin"/><p>Making room for your next hello…</p></div>:bootError?<div className="boot"><Brand/><h2>Let’s get connected.</h2><p>{bootError}</p><Button onClick={initialize}>Try again</Button><p className="muted">Start the local server using the project’s start instructions.</p></div>:view==='traffic'?<OwnerTraffic user={user} onAuth={setAuth} onBack={()=>navigate('video')}/>:!user||view==='video'?<RandomChat user={user} config={config} onAuth={setAuth} onAccount={()=>navigate('profile')} onTraffic={()=>navigate('traffic')} onLogout={logout} onPolicy={setPolicy} onReport={setReport} notify={notify}/>:<div className="app-shell"><aside className={`sidebar ${mobileMenu?'mobile-open':''}`}><div className="sidebar-brand"><Brand/><button className="icon-button mobile-close" onClick={()=>setMobileMenu(false)} aria-label="Close navigation"><X size={20}/></button></div><div className="sidebar-tagline">Good things start with hello.</div><nav className="sidebar-nav" aria-label="Main navigation">{nav.map(([id,label,Icon])=><button className={view===id?'active':''} onClick={()=>navigate(id)} key={id}><Icon size={19}/><span>{label}</span>{id==='connections'&&invitations>0?<b>{invitations}</b>:id==='messages'&&unread>0?<b>{unread}</b>:null}{view===id&&<span className="nav-active-dot"/>}</button>)}{user.canViewTraffic&&<button onClick={()=>navigate('traffic')}><LockKeyhole size={19}/>Private traffic</button>}{user.role==='admin'&&<button className={view==='admin'?'active':''} onClick={()=>navigate('admin')}><ShieldBan size={19}/>Moderation</button>}</nav><div className="sidebar-note"><span className="sidebar-note-star">✳</span><h3>Be a little<br/>more you.</h3><p>The right conversation starts with being yourself.</p><button onClick={()=>navigate('profile')}>Manage your account <ArrowUpRight size={15}/></button></div><div className="sidebar-bottom"><button className={`sidebar-profile ${view==='profile'?'active':''}`} onClick={()=>navigate('profile')}><Avatar person={user}/><div><strong>{user.name}</strong><span>Your account</span></div><Settings size={16}/></button><button className="sidebar-logout" onClick={logout}><LogOut size={15}/>Log out</button><div className="sidebar-policy"><button onClick={()=>setPolicy('privacy')}>Privacy</button><span>·</span><button onClick={()=>setPolicy('terms')}>Terms</button><span>·</span><button onClick={()=>setPolicy('guidelines')}>Guidelines</button></div></div></aside>{mobileMenu&&<button className="mobile-scrim" aria-label="Close navigation" onClick={()=>setMobileMenu(false)}/>}<div className="app-main"><header className="app-topbar"><button className="icon-button mobile-toggle" aria-label="Open navigation" onClick={()=>setMobileMenu(true)}><Menu size={22}/></button><span className="topbar-greeting">A good day for a new hello<span> ☀</span></span><div className="topbar-right">{config.demo&&<span className="preview-pill"><span/>Local preview · sample profiles</span>}{installPrompt&&<button className="install-button" onClick={async()=>{await installPrompt.prompt();setInstallPrompt(null);}}><Download size={15}/>Install</button>}<button className="topbar-avatar" aria-label="Open your account" onClick={()=>navigate('profile')}><Avatar person={user} size="small"/></button></div></header>{incomingCall&&video===undefined&&<div className="incoming-call"><Video size={20}/><div><strong>{incomingCall.person.name} is calling</strong><span>Review the camera rules before answering.</span></div><Button onClick={()=>setVideo({...incomingCall.person,connectionId:incomingCall.connectionId,incomingCallId:incomingCall.id})}>Review call</Button><button className="icon-button" aria-label="Decline video call" onClick={()=>{post(`/video/calls/${incomingCall.id}/respond`,{accept:false}).catch(e=>notify(e.message,'error'));setIncomingCall(null);}}><X size={19}/></button></div>}<main id="main-content" className={`page-content ${view==='messages'?'messages-page':''}`}><a className="skip-link" href="#main-content">Skip to content</a>{view==='discover'?<Discover people={people} user={user} onConnect={connect} onOpen={setDetail} onReport={setReport} busy={busy} onFilter={()=>setPrefs(true)} filters={filters}/>:view==='connections'?<Connections connections={connections} onRespond={respond} onChat={openChat} busy={busy}/>:view==='messages'?<Messages connections={connections} selected={selected} onSelect={setSelected} user={user} onReport={setReport} onVideo={setVideo} onRefresh={refresh} notify={notify}/>:view==='safety'?<Safety onPolicy={setPolicy} onVideo={setVideo}/>:view==='profile'?<ProfileSettings key={user.id} user={user} onUser={updateUser} config={config} notify={notify} onLogout={()=>{setUser(null);setView('video');}}/>:view==='admin'&&user.role==='admin'?<Admin notify={notify}/>:null}</main><footer className="app-footer"><span>Made for a little more connection.</span><span><ShieldCheck size={13}/>18+ · Respect comes first</span></footer></div></div>}{resetToken&&<ResetDialog token={resetToken} onClose={()=>setResetToken(null)} onDone={()=>{setResetToken(null);setUser(null);setAuth('login');notify('Password reset. Sign in with your new password.');}}/>}{auth&&<AuthDialog mode={auth} onClose={()=>setAuth(null)} onUser={updateUser} config={config} onPolicy={setPolicy}/>} {policy&&<PolicyDialog kind={policy} onClose={()=>setPolicy(null)}/>} {report&&<ReportDialog person={report} onClose={()=>setReport(null)} onDone={m=>{notify(m);setDetail(null);setSelected(null);refresh();}}/>}{video!==undefined&&<VideoDialog person={video} config={config} onClose={()=>setVideo(undefined)}/>} {prefs&&<PreferencesDialog filters={filters} user={user} onUser={updateUser} onSave={f=>{setFilters(f);setTimeout(refresh,0);}} onClose={()=>setPrefs(false)} notify={notify}/>} {detail&&<Modal title={`${detail.name}, ${detail.age}`} onClose={()=>setDetail(null)}><Avatar person={detail} art size="detail"/><div className="detail-copy"><div className="location"><MapPin size={14}/>{detail.city}{detail.isDemo?' · Fictional sample profile':''}</div><p>{detail.bio}</p><div className="tags">{detail.interests.map(i=><span key={i}>{interestIcons[i]} {i}</span>)}</div><Button className="full" disabled={!!detail.connectionStatus&&!detail.incoming&&detail.connectionStatus!=='accepted'} onClick={()=>{connect(detail);setDetail(null);}}>{detail.connectionStatus==='accepted'?'Open conversation':detail.incoming?'View invitation':detail.connectionStatus?'Hello already sent':'Say hello'}<Heart size={16}/></Button><button className="text-link report-profile" onClick={()=>{setReport(detail);setDetail(null);}}>Report or block this person</button></div></Modal>}{toast&&<div className={`toast ${toast.type}`} role="status">{toast.type==='error'?<AlertTriangle size={18}/>:<Check size={18}/>}<span>{toast.message}</span><button aria-label="Dismiss notification" onClick={()=>setToast(null)}><X size={16}/></button></div>}</>;
}
